import{_ as t,a,o as s,a6 as o}from"./chunks/framework.CJDy2q7X.js";const b=JSON.parse('{"title":"Section Fields","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"rest","title":"Section Fields","query":"curl -X GET \\"https://your-domain.com/api/admin/appearance/sections/15/fields?locale=en\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\"\\n","response":"{\\n  \\"sectionId\\": 15,\\n  \\"type\\": \\"static_content\\",\\n  \\"locale\\": \\"en\\",\\n  \\"schema\\": [\\n    { \\"name\\": \\"html\\", \\"type\\": \\"textarea\\", \\"label\\": \\"HTML\\" },\\n    { \\"name\\": \\"css\\", \\"type\\": \\"textarea\\", \\"label\\": \\"CSS\\" }\\n  ],\\n  \\"options\\": { \\"html\\": \\"<h2>Summer sale</h2>\\", \\"css\\": \\".sale { color: #c00; }\\" }\\n}\\n"}]},"headers":[],"relativePath":"api/rest-api/admin/appearance/sections/fields.md","filePath":"api/rest-api/admin/appearance/sections/fields.md","lastUpdated":1789385991000}'),r={name:"api/rest-api/admin/appearance/sections/fields.md"};function d(i,e,n,h,l,c){return s(),a("div",null,e[0]||(e[0]=[o('<h1 id="section-fields" tabindex="-1">Section Fields <a class="header-anchor" href="#section-fields" aria-label="Permalink to &quot;Section Fields&quot;">​</a></h1><p>The field set a section&#39;s type is built from, together with the values it currently holds. This is what makes a client-side editor possible without knowing the six types in advance: render the <code>schema</code>, fill it from <code>options</code>, and post the result back to <a href="/api/rest-api/admin/appearance/sections/draft.html">Stage edits</a>.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/admin/appearance/sections/{id}/fields</code></td><td>Get the editable fields of a section</td></tr></tbody></table><h2 id="path-parameters" tabindex="-1">Path parameters <a class="header-anchor" href="#path-parameters" aria-label="Permalink to &quot;Path parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>Section ID.</td></tr></tbody></table><h2 id="query-parameters" tabindex="-1">Query parameters <a class="header-anchor" href="#query-parameters" aria-label="Permalink to &quot;Query parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>locale</code></td><td>Locale the options are read in. Must be one the channel runs; otherwise the app locale, then the channel&#39;s first locale.</td></tr></tbody></table><h2 id="response-fields" tabindex="-1">Response fields <a class="header-anchor" href="#response-fields" aria-label="Permalink to &quot;Response fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>sectionId</code></td><td>integer</td><td>Section the fields belong to.</td></tr><tr><td><code>type</code></td><td>string</td><td>Section type the schema describes.</td></tr><tr><td><code>locale</code></td><td>string</td><td>Locale the options were read in.</td></tr><tr><td><code>schema</code></td><td>array</td><td>The field set for the type. Shape is decided by the type.</td></tr><tr><td><code>options</code></td><td>object</td><td>Values currently held — staged when there are any, otherwise published. Empty object for a section with no content yet.</td></tr></tbody></table><h2 id="use-cases" tabindex="-1">Use cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use cases&quot;">​</a></h2><ul><li><strong>Render an editor for any section type</strong> — one code path handles all six, because the schema describes the fields and <code>options</code> supplies the values.</li><li><strong>Round-trip an edit</strong> — read <code>options</code> here, change what the merchant edited, post the whole object to the draft endpoint.</li></ul><h2 id="best-practices" tabindex="-1">Best practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best practices&quot;">​</a></h2><ul><li><strong><code>options</code> resolves staged over published.</strong> A section holding a draft returns the draft, which is what the editor should show; read <a href="/api/rest-api/admin/appearance/sections/detail.html">Get section</a> when you specifically need the published values.</li><li><strong>Ask per locale.</strong> The response covers the one locale requested, so a translation editor calls this once per locale rather than expecting them all at once.</li></ul><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>When</th></tr></thead><tbody><tr><td><code>404</code></td><td>No section with this ID.</td></tr></tbody></table><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Requires <code>appearance.sections</code>.</p>',18)]))}const u=t(r,[["render",d]]);export{b as __pageData,u as default};
